//! **Model profiles** (v3 Q2): which token techniques are on for which model - generated by `sdcd bench profiles`
//! from bench comparisons that passed the Q3 rule, never written by hand.
//!
//! The bundled `protocol/model-profiles.json` is the release's; `<data>/model-profiles.json`, when present, is a
//! newer one (the knowledge job will write it, I11). A model the file does not name gets the conservative profile:
//! no token technique beyond what v1 already did.

use std::collections::{HashMap, HashSet};
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

pub const BUNDLED: &str = include_str!("../../../protocol/model-profiles.json");

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct Profile {
    /// Token techniques that passed Q3 on this model.
    #[serde(default)]
    pub techniques: Vec<String>,
    /// The comparisons that decided it, for the record.
    #[serde(default)]
    pub evidence: Vec<String>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct Profiles {
    #[serde(default)]
    pub generated: String,
    /// By `provider:model` (or `*:model` for a model on any provider).
    #[serde(default)]
    pub models: HashMap<String, Profile>,
}

impl Profiles {
    pub fn parse(text: &str) -> Self {
        serde_json::from_str(text).unwrap_or_default()
    }

    /// The techniques on for a model, by its provider and id.
    pub fn techniques(&self, provider: &str, model: &str) -> HashSet<String> {
        let bare = model.rsplit('/').next().unwrap_or(model);

        [format!("{provider}:{model}"), format!("{provider}:{bare}"), format!("*:{bare}")]
            .iter()
            .find_map(|key| self.models.get(key))
            .map(|profile| profile.techniques.iter().cloned().collect())
            .unwrap_or_default()
    }
}

/// The profiles in force: the data folder's newer file, or the bundled one.
pub fn current() -> &'static Profiles {
    static CURRENT: OnceLock<Profiles> = OnceLock::new();

    CURRENT.get_or_init(|| {
        crate::paths::data_dir()
            .ok()
            .and_then(|dir| std::fs::read_to_string(dir.join("model-profiles.json")).ok())
            .map(|text| Profiles::parse(&text))
            .filter(|profiles| !profiles.models.is_empty())
            .unwrap_or_else(|| Profiles::parse(BUNDLED))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The shipped profile is the bench's verdict, not a guess: on DeepSeek's chat model tool pruning and the code map
    /// passed the Q3 rule (`bench/results/q-one-*`), the other four did not - and every other model gets nothing.
    #[test]
    fn the_shipped_profile_holds_only_what_the_bench_accepted() {
        let shipped = Profiles::parse(BUNDLED);
        let on: std::collections::BTreeSet<String> = shipped.techniques("deepseek", "deepseek-chat").into_iter().collect();

        assert_eq!(on.into_iter().collect::<Vec<_>>(), ["repomap", "tool_pruning"]);
        assert!(shipped.techniques("openai-api", "gpt-5-nano").is_empty() && shipped.techniques("anthropic-api", "claude-sonnet-5-5").is_empty());
        assert!(shipped.models["deepseek:deepseek-chat"].evidence.len() == 6, "every technique's verdict is on record");
    }

    #[test]
    fn the_bundled_file_parses_and_unknown_models_get_nothing() {
        let bundled = Profiles::parse(BUNDLED);

        assert!(bundled.techniques("someone", "unknown-model").is_empty());

        let profiles = Profiles::parse(r#"{ "models": { "deepseek:deepseek-chat": { "techniques": ["stable_prefix", "ledger_diff"] }, "*:qwen3-coder-plus": { "techniques": ["skeleton"] } } }"#);

        assert!(profiles.techniques("deepseek", "deepseek-chat").contains("ledger_diff"));
        assert!(profiles.techniques("openrouter", "qwen/qwen3-coder-plus").contains("skeleton"), "a model on any provider");
        assert!(profiles.techniques("openai", "deepseek-chat").is_empty());
    }
}
